10	 * duplicate (its {@link OwnerIdentity#key(String, String, String) identity key} differs from every
11	 * existing owner's — see {@link RequireUniqueIdentity}) but whose surname is phonetically the same
12	 * ({@link Soundex} of the last name) and whose postcode matches an existing owner is a
13	 * <em>possible</em> duplicate: it is still created, but {@code possibleDuplicate} is set {@code true}
14	 * and {@code possibleDuplicateOf} to the matching owner's id. Otherwise {@code possibleDuplicate} is
15	 * {@code false} and {@code possibleDuplicateOf} is left unset.
16	 *
17	 * <p>A declared household member (the request set {@code sharesHousehold} to bypass the duplicate
18	 * block) is <em>not</em> a suspected duplicate: it shares an existing owner's surname and postcode by
19	 * declaration, so it is never flagged, whatever its telephone.
20	 *
21	 * <p>The match is on soundex(lastName) and postcode; an existing owner whose identity key equals the
22	 * new owner's would already have been rejected as a hard duplicate, so it is skipped here defensively.
23	 * When several existing owners match, the one with the lowest id (the earliest) is reported. Runs
24	 * after {@link BuildOwner} so the owner's telephone is already normalized, and before
25	 * {@link SaveOwner} so the owner being created is not compared against itself.
26	 */
27	public class FlagPossibleDuplicate {
28	
29	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
30	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            owner.setPossibleDuplicate(false); // a declared household member is not a suspected duplicate
32	            owner.setPossibleDuplicateOf(null);
33	            return;
34	        }
35	        String postcode = owner.getPostcode();
36	        String soundex = Soundex.of(owner.getLastName());
37	        String identityKey = OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
38	        Integer matchId = null;
39	        if (postcode != null && !postcode.isBlank()) {
40	            for (Owner existing : ownerRepository.findAll()) {
41	                if (Boolean.TRUE.equals(existing.getDeleted())) {
42	                    continue; // a soft-deleted owner is not a possible-duplicate match
43	                }
44	                if (existing.getId() == null || !postcode.equals(existing.getPostcode())
45	                        || !soundex.equals(Soundex.of(existing.getLastName()))) {
46	                    continue;
47	                }
48	                if (identityKey.equals(OwnerIdentity.key(existing.getTelephone(), existing.getEmail(),
49	                        existing.getLastName()))) {
