5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Step of {@code POST /api/owners} that records the owner's {@code bulkSignupWarning}: {@code true}
11	 * when more than 80 owners had already been created on the same adjusted business day (by
12	 * {@link Owner#getRegistrationDate()}) before this owner, otherwise {@code false}. Uses the same
13	 * per-day accumulation as {@link RequireDailyRegistrationLimit}. Runs before {@link SaveOwner} so
14	 * the owner being created is not itself counted.
15	 */
16	public class FlagBulkSignupWarning {
17	
18	    /** Threshold above which a create is flagged as part of a bulk signup. */
19	    private static final int BULK_SIGNUP_THRESHOLD = 80;
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
22	        LocalDate registrationDate = owner.getRegistrationDate();
23	        int count = 0;
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (registrationDate.equals(existing.getRegistrationDate())) {
26	                count++;
27	            }
28	        }
29	        owner.setBulkSignupWarning(count > BULK_SIGNUP_THRESHOLD);
30	    }
31	}
